import json
def P(i,x,y,ball=False,t=None):
    t=t or ("X" if i.startswith("x") else "O")
    d={"id":i,"team":t,"x":x,"y":y}
    if ball: d["ball"]=True
    return d
def A(t,f,path=None,to=None):
    d={"type":t,"from":f}
    if path: d["path"]=path
    if to: d["to"]=to
    return d
def S(cap,players,actions): return {"caption":cap,"players":players,"actions":actions}
def item(i,cat,name,level,players,leagues,desc,points,src,srcName,tags,steps,note=None):
    d=dict(kind="play",category=cat,name=name,level=level,players=players,leagues=leagues,minutes=None,description=desc,points=points,source=src,sourceName=srcName,tags=tags,diagram={"court":"half","steps":steps})
    if note: d["sourceNote"]=note
    return {"id":i,"data":d}
